// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type PatternMatchProps = Record<string, any>;

type ShapeType = 'square' | 'circle' | 'triangle' | 'question';

interface RenderShapeProps {
  type: ShapeType;
  color: string;
  font: string;
  questionTextColor: string;
}

const RenderShape: React.FC<RenderShapeProps> = ({ type, color, font, questionTextColor }) => {
  const shadow = 'drop-shadow(0px 12px 16px rgba(0,0,0,0.15))';
  
  if (type === 'square') {
    return (
      <svg width="100%" height="100%" viewBox="0 0 100 100" style={{ overflow: 'visible', filter: shadow }}>
        <rect x="15" y="15" width="70" height="70" rx="16" fill={color} />
      </svg>
    );
  }
  if (type === 'circle') {
    return (
      <svg width="100%" height="100%" viewBox="0 0 100 100" style={{ overflow: 'visible', filter: shadow }}>
        <circle cx="50" cy="50" r="35" fill={color} />
      </svg>
    );
  }
  if (type === 'triangle') {
    return (
      <svg width="100%" height="100%" viewBox="0 0 100 100" style={{ overflow: 'visible', filter: shadow }}>
        <path d="M 50 18 L 85 75 L 15 75 Z" fill={color} stroke={color} strokeWidth="12" strokeLinejoin="round" />
      </svg>
    );
  }
  if (type === 'question') {
    return (
      <svg width="100%" height="100%" viewBox="0 0 100 100" style={{ overflow: 'visible', filter: shadow }}>
        <rect x="15" y="15" width="70" height="70" rx="16" fill={color} />
        <text x="50" y="67" fill={questionTextColor} fontSize="52" fontWeight="800" fontFamily={font} textAnchor="middle">?</text>
      </svg>
    );
  }
  return null;
};

const PatternMatch: React.FC<PatternMatchProps> = ({
  backgroundColor = "#FF4D4D",
  transparentBackground = false,
  durationInSeconds = 6,
  shape1Color = "#FFFFFF",
  shape2Color = "#FFD700",
  shape3Color = "#222222",
  questionBoxColor = "#FFFFFF",
  titleText = "FIND THE PATTERN",
  successText = "MATCH!",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const minDim = Math.min(width, height);

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // The pattern sequence mapped visually
  const sequence: Array<{ type: ShapeType; color: string; targetColor?: string }> = [
    { type: 'square', color: shape1Color },
    { type: 'circle', color: shape2Color },
    { type: 'triangle', color: shape3Color },
    { type: 'square', color: shape1Color },
    { type: 'circle', color: shape2Color },
    { type: 'question', color: questionBoxColor, targetColor: shape3Color },
  ];

  // Title Animation
  const titlePop = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 100 }
  });
  const titleY = interpolate(titlePop, [0, 1], [-minDim * 0.05, 0]);
  
  // Success Text Animation
  const successPop = spring({
    frame: frame - 130,
    fps,
    config: { damping: 10, mass: 1, stiffness: 120 }
  });

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: spaceGrotesk,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        padding: '4%',
        transition: 'none'
      }}
    >
      {/* Title Section */}
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <h1 style={{
          fontSize: minDim * 0.08,
          fontWeight: 700,
          color: '#FFFFFF',
          textTransform: 'uppercase',
          letterSpacing: '0.05em',
          margin: 0,
          transform: `translateY(${titleY}px)`,
          opacity: titlePop,
          textAlign: 'center',
          textShadow: `0px ${minDim * 0.005}px ${minDim * 0.015}px rgba(0,0,0,0.15)`,
          transition: 'none'
        }}>
          {titleText}
        </h1>
      </div>

      {/* Grid Pattern Section (Optimized for 16:9 with horizontal flow) */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(6, 1fr)',
        gap: `${minDim * 0.05}px`,
        width: `${width * 0.85}px`,
        transition: 'none'
      }}>
        {sequence.map((item, index) => {
          const isLast = index === sequence.length - 1;

          // 1. Initial Pop In
          const popInSpring = spring({
            frame: frame - index * 6,
            fps,
            config: { damping: 12, mass: 0.8, stiffness: 100 }
          });

          // 2. Hopping Effect to "read" the pattern
          const hopStartFrame = 40 + index * 10;
          const hopUpSpring = spring({ frame: frame - hopStartFrame, fps, config: { damping: 12, mass: 0.5, stiffness: 150 } });
          const hopDownSpring = spring({ frame: frame - hopStartFrame - 8, fps, config: { damping: 12, mass: 0.5, stiffness: 150 } });
          
          const hopY = (hopUpSpring - hopDownSpring) * (-minDim * 0.04);
          const hopScale = 1 + Math.max(0, hopUpSpring - hopDownSpring) * 0.15;
          const currentScale = popInSpring * hopScale;

          // 3. Flip Effect for the last item to reveal the answer
          const flipSpring = spring({
            frame: frame - 110,
            fps,
            config: { damping: 14, mass: 1, stiffness: 100 }
          });
          const rotateY = isLast ? interpolate(flipSpring, [0, 1], [0, 180]) : 0;

          // 4. Ring Burst for correct match
          const ringProgressFrames = Math.max(0, frame - 125);
          const ringScale = interpolate(ringProgressFrames, [0, 30], [0.5, 2.5], { extrapolateRight: 'clamp' });
          const ringOpacity = interpolate(ringProgressFrames, [0, 10, 30], [0, 1, 0], { extrapolateRight: 'clamp' });

          return (
            <div key={index} style={{
              position: 'relative',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              transform: `scale(${currentScale}) translateY(${hopY}px)`,
              perspective: `${minDim * 1.5}px`,
              aspectRatio: '1/1',
              transition: 'none'
            }}>
              <div style={{
                width: '100%',
                height: '100%',
                position: 'relative',
                transformStyle: 'preserve-3d',
                transform: `rotateY(${rotateY}deg)`,
                transition: 'none'
              }}>
                {/* Front Side */}
                <div style={{ position: 'absolute', inset: 0, backfaceVisibility: 'hidden', transition: 'none' }}>
                  <RenderShape type={item.type} color={item.color} font={spaceGrotesk} questionTextColor={backgroundColor} />
                </div>

                {/* Back Side (Target matching shape) */}
                {isLast && item.targetColor && (
                  <div style={{ position: 'absolute', inset: 0, backfaceVisibility: 'hidden', transform: 'rotateY(180deg)', transition: 'none' }}>
                    <RenderShape type="triangle" color={item.targetColor} font={spaceGrotesk} questionTextColor={backgroundColor} />
                  </div>
                )}
              </div>

              {/* Success Burst Ring on the final item */}
              {isLast && (
                <div style={{
                  position: 'absolute',
                  top: '15%', left: '15%', right: '15%', bottom: '15%',
                  borderRadius: '50%',
                  border: `${minDim * 0.008}px solid ${item.targetColor}`,
                  opacity: ringOpacity,
                  transform: `scale(${ringScale})`,
                  pointerEvents: 'none',
                  zIndex: -1,
                  transition: 'none'
                }} />
              )}
            </div>
          );
        })}
      </div>

      {/* Success Text Section */}
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <h2 style={{
          fontSize: minDim * 0.12,
          fontWeight: 800,
          color: shape3Color,
          textTransform: 'uppercase',
          letterSpacing: '0.05em',
          margin: 0,
          transform: `scale(${successPop})`,
          opacity: successPop,
          textAlign: 'center',
          textShadow: `0px ${minDim * 0.01}px ${minDim * 0.025}px rgba(0,0,0,0.25)`,
          transition: 'none'
        }}>
          {successText}
        </h2>
      </div>
    </AbsoluteFill>
  );
};

export default PatternMatch;